<?php
// Cheapest enabled variant drives the shown "From" price and any sale badge.
$cheap = null;
foreach ($product['variants'] as $candidate) { if (!(int)$candidate['enabled']) continue; if ($cheap === null || (int)$candidate['unit_price_minor'] < (int)$cheap['unit_price_minor']) $cheap = $candidate; }
$origMinor = $cheap && $cheap['original_price_minor'] !== null && (int)$cheap['original_price_minor'] > (int)$cheap['unit_price_minor'] ? (int)$cheap['original_price_minor'] : null;
$salePercent = $origMinor ? (int)round(($origMinor - (int)$cheap['unit_price_minor']) / $origMinor * 100) : 0;
$saved = in_array((int)$product['id'], $navWishlist ?? [], true);
?>
<article class="stone-card"><a class="stone-image" href="<?= $u('product/' . $product['slug']) ?>"><?php if ($product['images']): ?><img loading="lazy" src="<?= $u($product['images'][0]['path']) ?>" alt="<?= $e($product['images'][0]['alt_text']) ?>"><?php else: ?><span class="material-placeholder">Natural stone<br>Image coming soon</span><?php endif; ?><?php if (empty($product['in_stock'])): ?><span class="badge badge-out">Out of stock</span><?php elseif ($salePercent > 0): ?><span class="badge badge-sale"><?= $salePercent ?>% OFF</span><?php elseif (!empty($product['featured'])): ?><span class="badge">Featured</span><?php endif; ?></a><form class="save-stone-form" method="post" action="<?= $u('wishlist') ?>" data-wishlist><input type="hidden" name="csrf" value="<?= $e(RequestSecurity::csrfToken()) ?>"><input type="hidden" name="product_id" value="<?= $e($product['id']) ?>"><input type="hidden" name="action" value="<?= $saved ? 'remove' : 'add' ?>"><button class="save-stone<?= $saved ? ' saved' : '' ?>" aria-pressed="<?= $saved ? 'true' : 'false' ?>" aria-label="<?= $saved ? 'Remove from saved materials' : 'Save material' ?>" data-tip="<?= $saved ? 'Saved' : 'Save' ?>"><?= $icon('heart') ?></button></form><?php /* Compare hidden storefront-wide:
<form class="compare-stone-form" method="post" action="<?= $u('compare') ?>"><input type="hidden" name="csrf" value="<?= $e(RequestSecurity::csrfToken()) ?>"><input type="hidden" name="product_id" value="<?= $e($product['id']) ?>"><button class="compare-stone" aria-label="Compare material" data-tip="Compare"><?= $icon('compare') ?></button></form>
*/ ?><span class="brand-tag"><?= $e($product['brand_name'] ?? $product['category_name']) ?></span><h3><a href="<?= $u('product/' . $product['slug']) ?>"><?= $e($product['name']) ?></a></h3><p class="stone-meta"><?= $e($product['category_name']) ?></p><?php if (!empty($product['review_count'])): ?><a class="stone-rating" href="<?= $u('product/' . $product['slug']) ?>#reviews"><?= $stars($product['rating_tenths'], 'sm') ?><b><?= number_format($product['rating_tenths'] / 10, 1) ?></b><small>(<?= (int)$product['review_count'] ?>)</small></a><?php endif; ?><div class="stone-price"><?php if ((int)$product['min_price_minor'] > 0): ?><strong>From <?= $m($product['min_price_minor']) ?></strong><?php if ($origMinor): ?><del><?= $m($origMinor) ?></del><?php endif; ?><?php else: /* unpriced stock would otherwise advertise "From ₹0.00" */ ?><strong class="price-unset">Price on request</strong><?php endif; ?></div><div class="card-bottom"><span><?= $product['in_stock'] ? 'In stock' : 'Currently unavailable' ?></span><a href="<?= $u('product/' . $product['slug']) ?>">Explore</a></div><div class="card-cta"><?php $quickProduct = $product; $quickClass = 'button secondary card-add'; $quickLabel = $icon('bag') . 'Add'; $quickUnavailable = ''; require __DIR__ . '/quick_add.php'; ?><?php if ($quickVariant): ?><form class="quick-buy" method="post" action="<?= $u('buy-now') ?>"><input type="hidden" name="csrf" value="<?= $e(RequestSecurity::csrfToken()) ?>"><input type="hidden" name="variant_id" value="<?= $e($quickVariant['id']) ?>"><input type="hidden" name="quantity" value="<?= $q($quickVariant['qty_increment_milli']) ?>"><input type="hidden" name="purchase_key" value="<?= $e(bin2hex(random_bytes(16))) ?>"><button class="button card-buy">Buy now</button></form><?php endif; ?></div></article>
